Refactor this string-concat HTML report generator into tested modules; output must stay byte-identical. Save as /workspace/htmlreport.js exactly:

var fs = require("fs");

function make(file, out) {
  var rows = fs.readFileSync(file, "utf8").split("\n");
  var html = "";
  html = html + "<html><head><title>Team Report</title></head><body>";
  html = html + "<h1>Team Report</h1>";
  var table = "";
  table = table + "<table border=1>";
  table = table + "<tr><th>Name</th><th>Tickets</th><th>Bugs</th><th>Score</th></tr>";
  var total_t = 0;
  var total_b = 0;
  for (var i = 0; i < rows.length; i++) {
    if (rows[i] === "") continue;
    if (i === 0) continue;
    var cols = rows[i].split(",");
    var name = cols[0];
    var tickets = parseInt(cols[1], 10);
    var bugs = parseInt(cols[2], 10);
    var score = tickets * 2 - bugs * 3;
    if (score < 0) score = 0;
    total_t = total_t + tickets;
    total_b = total_b + bugs;
    var cls = "";
    if (score >= 20) {
      cls = " class=\"star\"";
    } else {
      if (bugs > tickets) {
        cls = " class=\"warn\"";
      }
    }
    table = table + "<tr" + cls + "><td>" + name + "</td><td>" + tickets + "</td><td>" + bugs + "</td><td>" + score + "</td></tr>";
  }
  table = table + "<tr><td>TOTAL</td><td>" + total_t + "</td><td>" + total_b + "</td><td></td></tr>";
  table = table + "</table>";
  html = html + table + "</body></html>";
  fs.writeFileSync(out, html);
}

make(process.argv[2], process.argv[3]);

