// Pure report-building functions. Refactored from the legacy string-concat
// script (htmlreport.js). Output must stay byte-identical; the golden test
// (tests/report.golden.test.mjs) enforces this bit-for-bit.

/**
 * Parse CSV text into data row objects.
 *
 * Frozen legacy behavior (kept for byte-identical output):
 * - Splits on "\n" only (no "\r\n" handling).
 * - Skips line index 0 entirely (header row).
 * - Skips empty lines anywhere, including the trailing empty element
 *   produced by a final newline.
 * - No quoting/escaping support: naive split(",").
 *
 * @param {string} text full CSV file contents
 * @returns {Array<{name: string, tickets: number, bugs: number}>}
 */
export function parseCsv(text) {
  const lines = text.split("\n");
  const rows = [];
  for (let i = 0; i < lines.length; i++) {
    if (lines[i] === "") continue;
    if (i === 0) continue;
    const cols = lines[i].split(",");
    rows.push({
      name: cols[0],
      tickets: parseInt(cols[1], 10),
      bugs: parseInt(cols[2], 10),
    });
  }
  return rows;
}

/**
 * Compute a row's score: tickets * 2 - bugs * 3, clamped to a minimum of 0.
 * @param {{tickets: number, bugs: number}} row
 * @returns {number}
 */
export function scoreRow(row) {
  let score = row.tickets * 2 - row.bugs * 3;
  if (score < 0) score = 0;
  return score;
}

/**
 * Row CSS class. Precedence is frozen legacy behavior:
 * "star" (score >= 20) beats "warn" (bugs > tickets) when both would apply.
 *
 * @param {{tickets: number, bugs: number, score: number}} row
 * @returns {"star"|"warn"|""} "" means no class attribute
 */
export function rowClass(row) {
  if (row.score >= 20) {
    return "star";
  }
  if (row.bugs > row.tickets) {
    return "warn";
  }
  return "";
}

/**
 * Render the complete HTML report. Deliberately unescaped name cells are
 * FROZEN LEGACY BEHAVIOR: names are interpolated verbatim, so HTML in a
 * name (e.g. "<b>Ampersand & Sons</b>") lands in the document raw. Do not
 * "fix" this here without regenerating tests/golden/report.html on purpose.
 *
 * @param {Array<{name: string, tickets: number, bugs: number}>} rows data rows (no header)
 * @returns {string} complete HTML document
 */
export function renderHtml(rows) {
  let html = "<html><head><title>Team Report</title></head><body>";
  html += "<h1>Team Report</h1>";
  html += "<table border=1>";
  html += "<tr><th>Name</th><th>Tickets</th><th>Bugs</th><th>Score</th></tr>";
  let totalT = 0;
  let totalB = 0;
  for (const row of rows) {
    const score = scoreRow(row);
    totalT += row.tickets;
    totalB += row.bugs;
    const cls = rowClass({ ...row, score });
    const attr = cls === "" ? "" : ` class="${cls}"`;
    html +=
      "<tr" + attr + "><td>" + row.name + "</td><td>" + row.tickets +
      "</td><td>" + row.bugs + "</td><td>" + score + "</td></tr>";
  }
  html += "<tr><td>TOTAL</td><td>" + totalT + "</td><td>" + totalB + "</td><td></td></tr>";
  html += "</table>";
  html += "</body></html>";
  return html;
}

