// Unit tests for lib/report.mjs pure functions:
// - scoreRow: formula + clamping to 0
// - rowClass: star/warn precedence ("star" wins when both would apply)
import assert from "node:assert/strict";
import test from "node:test";

import { parseCsv, rowClass, scoreRow } from "../lib/report.mjs";

test("scoreRow computes tickets*2 - bugs*3", () => {
  assert.equal(scoreRow({ tickets: 8, bugs: 1 }), 13);
  assert.equal(scoreRow({ tickets: 15, bugs: 2 }), 24);
});

test("scoreRow clamps negative scores to 0", () => {
  assert.equal(scoreRow({ tickets: 4, bugs: 6 }), 0); // -10
  assert.equal(scoreRow({ tickets: 1, bugs: 1 }), 0); // -1
});

test("scoreRow returns exactly 0 at the boundary", () => {
  assert.equal(scoreRow({ tickets: 3, bugs: 2 }), 0); // 6 - 6
});

test("rowClass: star when score >= 20", () => {
  assert.equal(rowClass({ tickets: 15, bugs: 2, score: 24 }), "star");
});

test("rowClass: warn when bugs > tickets (and score < 20)", () => {
  assert.equal(rowClass({ tickets: 4, bugs: 6, score: 0 }), "warn");
});

test("rowClass: empty string for plain rows", () => {
  assert.equal(rowClass({ tickets: 8, bugs: 1, score: 13 }), "");
});

test("rowClass precedence: star beats warn when both apply", () => {
  // Encodes current behavior: high score AND bugs > tickets -> "star".
  assert.equal(rowClass({ tickets: 10, bugs: 12, score: 20 }), "star");
  assert.equal(rowClass({ tickets: 20, bugs: 30, score: 50 }), "star");
});

test("rowClass boundary: score exactly 20 is star", () => {
  assert.equal(rowClass({ tickets: 10, bugs: 0, score: 20 }), "star");
});

test("parseCsv skips header and empty lines, parses ints", () => {
  const rows = parseCsv("Name,Tickets,Bugs\nA,3,1\n\nB,0,5\n");
  assert.deepEqual(rows, [
    { name: "A", tickets: 3, bugs: 1 },
    { name: "B", tickets: 0, bugs: 5 },
  ]);
});

