// Golden characterization test.
//
// The golden file tests/golden/report.html was generated ONCE from the
// LEGACY script (htmlreport.js) via scripts/gen-golden.mjs and is committed
// verbatim. This test runs the CURRENT binary (bin/htmlreport.mjs) on the
// same fixture and requires a BYTE-FOR-BYTE match, so any accidental change
// to output (including whitespace) fails here.
//
// FROZEN LEGACY BEHAVIOR documented on purpose:
// - Name cells are NOT HTML-escaped. A name like "<b>Ampersand & Sons</b>"
//   is emitted raw into the document (see the last fixture row). This quirk
//   is intentionally preserved; do not add escaping without consciously
//   regenerating the golden file.
import { execFileSync } from "node:child_process";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import { FIXTURE_CSV } from "../scripts/gen-golden.mjs";

const root = path.resolve(import.meta.dirname, "..");

test("bin/htmlreport.mjs output matches legacy golden byte-for-byte", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "htmlreport-test-"));
  const csv = path.join(dir, "in.csv");
  const out = path.join(dir, "out.html");
  // Fixture: header + 4 people covering star, warn, plain, score-clamped-to-0,
  // plus a 5th row whose name contains raw HTML/& to freeze no-escaping.
  fs.writeFileSync(csv, FIXTURE_CSV);

  execFileSync("node", [path.join(root, "bin", "htmlreport.mjs"), csv, out], {
    cwd: root,
  });

  const actual = fs.readFileSync(out); // Buffer -> byte comparison
  const golden = fs.readFileSync(path.join(root, "tests", "golden", "report.html"));
  assert.ok(actual.equals(golden), `output differs from golden\nactual:\n${actual}\ngolden:\n${golden}`);
});

