  const out = path.join(dir, "out.html");
  // Fixture: header + 4 people covering star, warn, plain, score-clamped-to-0,
  // plus a 5th row whose name contains raw HTML/& to freeze no-escaping.
  fs.writeFileSync(csv, FIXTURE_CSV);

  execFileSync("node", [path.join(root, "bin", "htmlreport.mjs"), csv, out], {
    cwd: root,
  });

  const actual = fs.readFileSync(out); // Buffer -> byte comparison
  const golden = fs.readFileSync(path.join(root, "tests", "golden", "report.html"));
  assert.ok(actual.equals(golden), `output differs from golden\nactual:\n${actual}\ngolden:\n${golden}`);
});
